/**
 * Checks the native projects generated by `expo prebuild` for permission mistakes
 * that config plugins can introduce silently (e.g. a plugin option that strips the
 * camera permission). Run after `expo prebuild --no-install`; CI does both.
 */
import { globSync, readFileSync } from 'node:fs';

const failures = [];
const manifest = readFileSync('android/app/src/main/AndroidManifest.xml', 'utf8');
const permission = (name) =>
  new RegExp(
    `<uses-permission android:name="android\\.permission\\.${name}"(?![^>]*tools:node="remove")`,
  ).test(manifest);

if (!permission('CAMERA')) failures.push('Android: the CAMERA permission is missing or removed');
// The microphone records sound with short videos (CAM-13).
if (!permission('RECORD_AUDIO'))
  failures.push('Android: the RECORD_AUDIO permission is missing or removed');
for (const forbidden of [
  'READ_EXTERNAL_STORAGE',
  'READ_MEDIA_IMAGES',
  'ACCESS_FINE_LOCATION',
  'ACCESS_COARSE_LOCATION',
]) {
  if (permission(forbidden)) failures.push(`Android: ${forbidden} must not be requested`);
}

const [plist] = globSync('ios/*/Info.plist');
if (plist === undefined) {
  failures.push('iOS: Info.plist not found (run expo prebuild first)');
} else {
  const info = readFileSync(plist, 'utf8');
  if (!info.includes('<key>NSCameraUsageDescription</key>'))
    failures.push('iOS: NSCameraUsageDescription is missing');
  if (!info.includes('<key>NSMicrophoneUsageDescription</key>'))
    failures.push('iOS: NSMicrophoneUsageDescription is missing');
  for (const forbidden of [
    'NSPhotoLibraryUsageDescription',
    'NSLocationWhenInUseUsageDescription',
    'NSFaceIDUsageDescription',
  ]) {
    if (info.includes(`<key>${forbidden}</key>`))
      failures.push(`iOS: ${forbidden} must not be declared`);
  }
}

if (failures.length > 0) {
  console.error(failures.join('\n'));
  process.exit(1);
}
console.log('Native permissions are as intended.');
